#!/usr/bin/env python3
"""Author data for records397--405. Text is editorial; raw strings preserve LaTeX."""
import json, csv, re
from pathlib import Path
ROOT=Path(__file__).resolve().parent
talks=[]; items=[]; problems=[]; corrections=[]
def talk(record,date,speaker,pages,title,kind,summary,**extra):
    talks.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind=kind,summary=summary,**extra))
def item(record,pages,kind,title,notes,statement,reconstruction,cls,fate,present,refs=(),literal='correct with missing hypotheses',match='exact',verification='read the result',confidence='high',problem='',area='',speaker=None,development='none'):
    n=1+sum(x['record']==record for x in items)
    d=dict(id=f'1976-{record}.{n}',record=record,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,
           **{'class':cls},fate=fate,present_status='As of 10 November 2026: '+present,literal_correctness=literal,publication_match=match,
           verification=verification,development=development,problem=problem,worth='',refs=list(refs),confidence=confidence,area=area)
    if speaker: d['speaker']=speaker
    items.append(d); return d['id']
def corr(page,place,reads,should,evidence,typ='faithful_error',applies='both'):
    def esc(z):
        mapping={'\\':r'\textbackslash{}','&':r'\&','%':r'\%','$':r'\$','#':r'\#','_':r'\_','{':r'\{','}':r'\}','~':r'\textasciitilde{}','^':r'\textasciicircum{}'}
        return ''.join(mapping.get(ch,ch) for ch in z)
    place,reads,should,evidence=map(esc,(place,reads,should,evidence))
    corrections.append(dict(page=page,place=place,transcription_reads=reads,should_read=should,evidence=evidence,applies_to=applies,type=typ))
def clean_prose(value):
    # Protect formulas, citation keys, identifiers and URLs while restoring prose spaces.
    protected=re.compile(r'\\\([\s\S]*?\\\)|\\\[[\s\S]*?\\\]|\\cite[tp](?:\[[^]]*\])?\{[^}]+\}|https?://\S+|\b(?:P\d{3,6}|GP-\d{4}-\d{2}|\d{4}-\d+\.\d+|I\d+|L2|H0)\b')
    def plain(z):
        z=re.sub(r'(?<=[A-Za-z])(?=\d)', ' ',z)
        z=re.sub(r'(?<=\d)(?=[A-Za-z])', ' ',z)
        z=re.sub(r'\bclass([A-F])\b',r'class \1',z)
        z=re.sub(r'\bClass([A-F])\b',r'Class \1',z)
        z=re.sub(r'(?<=[,;:])(?=[A-Za-z])',' ',z)
        for old,new in {'Yu.A.Gol':'Yu. A. Gol','I.M.Gelfand':'I. M. Gelfand','E.P.Likhtman':'E. P. Likhtman'}.items():
            z=z.replace(old,new)
        z=z.replace('entryR 18','entry R18')
        return z
    parts=[];pos=0
    for m in protected.finditer(value):
        parts.append(plain(value[pos:m.start()]))
        z=m.group()
        if z.startswith('\\cite') and '[' in z:
            a=z.index('[');b=z.index(']')
            loc=plain(z[a+1:b])
            loc=re.sub(r'(\\S(?:\\S)?)(?=\d)',r'\1~',loc)
            loc=re.sub(r'(Theorem|Proposition|equation|equations|no\.|pp\.|p\.|entry|Expos\\\'e) (?=\d)',r'\1~',loc)
            z=z[:a+1]+loc+z[b:]
        parts.append(z);pos=m.end()
    parts.append(plain(value[pos:]));return ''.join(parts)
def save():
    for data in (talks,items,problems,corrections):
        for row in data:
            for field in ('summary','notes','statement','reconstruction','fate','present_status','status','worth','title','place','transcription_reads','should_read','evidence'):
                if field in row: row[field]=clean_prose(row[field])
    for name,data in [('talks',talks),('items',items),('problems',problems)]:
        (ROOT/f'early_{name}.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
    with (ROOT/'early_corrections.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writeheader();w.writerows(corrections)

talk(397,'1976-09-06','I. M. Gelfand','P000659','A physics reading programme','plan',
 r'''The opening question is \ru{Что надо знать из физики?}; an uncertain marginal attribution says ``following Sinai?''. The programme lists classical and Hamiltonian mechanics; quantum mechanics and scattering; relativity and field theory; and quantum field theory, including second quantization, Bose and Fermi statistics, functional integrals, perturbation series, Feynman diagrams, renormalization and Yang--Mills fields. Arnold, Landau--Lifshitz, Fermi, Weinberg and Hepp are reading suggestions. Consultation with physicists and a typed version are requested. No theorem, calculation or definite research problem is stated, so the programme is preserved without manufacturing mathematical occurrences. Gindikin begins on the same page; the catalogue's P000659--P000660 window overlaps that next record.''',catalogue_pages='P000659-P000660')
talk(398,'1976-09-06','S. G. Gindikin, with I. M. Gelfand','P000659-P000662','SL(2,R), integral geometry and analytic separation of series','talk',
 r'''The group is represented as the determinant-one quadric, and the regular representation is studied through hyperplane and line integrals. Gelfand distinguishes separation into series from decomposition into individual irreducibles. The announced real-transform kernels isolate discrete and continuous parts; two complex domains then realize the positive and negative discrete parts as Hardy boundary values. The lecture ends with an explicit kernel and Arnold's conjecture identifying the domains by their fractional-linear action. The exact subsequent paper is \citet{gelfandgindikin1977complex}, received 6 June 1977. Its kernel has an additional nonconstant factor absent from the notebook. P000661--P000662 unmistakably continue this lecture, despite the catalogue's narrower page window.''',catalogue_pages='P000659-P000660')
